//! 🌊️ Original contributed metadata and input custody through physical wave serialization.
use super::*;
use super::super::{PendingExtensionEval,OperatorPendingPlan};
#[path="🔑️hash/🦀️.rs"]
mod hash;
use hash::NodeHashCursor;
#[derive(semio_framework_value::RetireOwned)]
struct WaveSources{control:Option<semio_framework_value::NativeEncodeContinuation>,plan:OperatorPendingPlan,hash:NodeHashCursor,writer:semio_framework_pack_json::JsonBorrowedWriteCursor,buffer:Vec<u8>,neuron_id:String,extension_id:String,operator_id:String,input_json:String}
/// 🌊️ Holds the same contributed input and metadata until the original pending wire is admitted.
pub struct PendingWaveCursor{sources:ManuallyDrop<Option<WaveSources>>,retirement:Option<ControlledRetirement<WaveSources>>,phase:u8,node_hash:u64,closing:bool,progress:RetainedCloneProgress}
impl PendingWaveCursor{
 pub fn new(plan:OperatorPendingPlan)->Self{Self{sources:ManuallyDrop::new(Some(WaveSources{control:None,plan,hash:NodeHashCursor::new(),writer:semio_framework_pack_json::JsonBorrowedWriteCursor::new(),buffer:Vec::new(),neuron_id:String::new(),extension_id:String::new(),operator_id:String::new(),input_json:String::new()})),retirement:None,phase:0,node_hash:0,closing:false,progress:Default::default()}}
 fn text<'a>(&'a self,neuron:&'a str)->&'a str{let fields=self.sources.as_ref().unwrap();match self.phase{0=>neuron,1=>&fields.plan.metadata.extension_id,2=>&fields.plan.metadata.operator_id,_=>unreachable!()}}
 pub fn progress(&self)->RetainedCloneProgress{self.progress}
 pub fn next_demands(&self,neuron:&str,copy:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.next_close_demands(copy)}let fields=self.sources.as_ref().unwrap();if self.phase<3{let text=self.text(neuron);return Ok(RetirementDemand{copy_bytes:usize::from(fields.buffer.len()<text.len()&&fields.buffer.capacity()>=text.len()),capacity_bytes:if fields.buffer.capacity()<text.len(){text.len()}else{0},depth:1,..Default::default()})}if self.phase==3{return Ok(fields.hash.demands(&fields.plan.metadata.operator_id,&fields.plan.input))}if self.phase==4{return fields.writer.normal_step_demands(&fields.plan.input)}Ok(RetirementDemand{depth:1,..Default::default()})}
 pub fn step(&mut self,neuron:&str,grant:RetainedCloneGrant)->Result<Option<PendingExtensionEval>,ValueError>{self.progress=Default::default();let result=self.advance(neuron,grant);result.map_err(|error|error.with_retained_progress(self.progress))}
 fn advance(&mut self,neuron:&str,grant:RetainedCloneGrant)->Result<Option<PendingExtensionEval>,ValueError>{if self.closing{return Err(ValueError::literal(ValueRefusalKind::Canceled,"original pending wave is closing"))}let d=self.next_demands(neuron,grant.maximum_copy_bytes)?;if grant.maximum_items==0{return Ok(None)}if grant.maximum_depth<d.depth{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"original pending wave requires admitted depth"))}if grant.maximum_copy_bytes<d.copy_bytes||grant.maximum_capacity_bytes<d.capacity_bytes||grant.maximum_release_bytes<d.release_bytes{return Ok(None)}if self.phase<3{let text=self.text(neuron);let pointer=text.as_ptr();let length=text.len();let fields=self.sources.as_mut().unwrap();self.progress.copied_items=1;if fields.buffer.capacity()<length{fields.buffer.try_reserve_exact(length).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"original wave text reservation refused"))?;self.progress.retained_capacity_bytes=fields.buffer.capacity();}else if fields.buffer.len()<length{let offset=fields.buffer.len();let count=(length-offset).min(grant.maximum_copy_bytes);unsafe{fields.buffer.extend_from_slice(std::slice::from_raw_parts(pointer.add(offset),count))}self.progress.copied_bytes=count;}else{let text=unsafe{String::from_utf8_unchecked(std::mem::take(&mut fields.buffer))};match self.phase{0=>fields.neuron_id=text,1=>fields.extension_id=text,2=>fields.operator_id=text,_=>unreachable!()}self.phase+=1;}return Ok(None)}let fields=self.sources.as_mut().unwrap();match self.phase{3=>{let result=fields.hash.step(&fields.plan.metadata.operator_id,&fields.plan.input,grant);self.progress=fields.hash.progress();if let Some(hash)=result?{self.node_hash=hash;self.phase=4}},4=>{let mut receive=|_|true;let mut control=match fields.control.take(){Some(receipt)=>semio_framework_value::NativeEncodeControl::resume(receipt,&mut receive)?,None=>semio_framework_value::NativeEncodeControl::new_retained(&mut receive)};let result=fields.writer.step(&fields.plan.input,1,&mut control,grant);self.progress=fields.writer.normal_step_progress();fields.control=Some(control.pause()?);if let Some(text)=result?{fields.input_json=text;self.phase=5}},5=>{self.phase=255;self.progress.copied_items=1;return Ok(Some(PendingExtensionEval{neuron_id:std::mem::take(&mut fields.neuron_id),extension_id:std::mem::take(&mut fields.extension_id),operator_id:std::mem::take(&mut fields.operator_id),node_hash:self.node_hash,input_json:std::mem::take(&mut fields.input_json)}))},_=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original pending wave was already transferred"))}Ok(None)}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn next_close_demands(&self,copy:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=self.retirement.as_ref(){return BudgetedEvalState::demands(owner,copy)}Ok(RetirementDemand{depth:usize::from(self.sources.is_some()),..Default::default()})}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.progress=Default::default();let result=self.close_original(grant);if let Ok(step)=&result{self.progress=step.progress()}result.map_err(|error|error.with_retained_progress(self.progress))}
 fn close_original(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original pending wave close was not requested"))}if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(owner)=self.retirement.as_mut(){let result=owner.step(grant);self.progress=owner.step_progress();let step=result?;if owner.terminal_is_empty(){self.retirement=None}return Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})}if grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"original wave root handoff requires depth"))}self.retirement=Some(ControlledRetirement::new(self.sources.take().unwrap()).unwrap_or_else(|_|unreachable!()));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.sources.is_none()&&self.retirement.is_none()}
}
impl Drop for PendingWaveCursor{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original pending wave requires explicit closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.sources)}}}}
struct WaveRetirement(PendingWaveCursor);
impl RetirementCursor for WaveRetirement{fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{match self.0.close_step(grant){Ok(step)if step.progress()!=Default::default()=>RetirementStep::Progress(step.progress()),Ok(RetainedCloneStep::Complete(_))=>RetirementStep::Complete,Ok(_)=>RetirementStep::BudgetExhausted,Err(error)=>RetirementStep::Failure(error)}}fn terminal_is_empty(&self)->bool{self.0.terminal_is_empty()}fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.0.next_close_demands(0)?.copy_bytes)}fn allows_admitted_narrow_work(&self)->bool{true}fn next_birth_bytes(&self,copy:usize)->Option<usize>{self.0.next_close_demands(copy).ok().map(|d|d.capacity_bytes)}fn next_close_byte_demand(&self)->Option<usize>{self.0.next_close_demands(0).ok().map(|d|d.release_bytes)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.0.next_close_demands(0)?.depth)}fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(std::mem::size_of::<Self>())}}
impl RetireOwned for PendingWaveCursor{fn retirement(mut self)->Box<dyn RetirementCursor>{self.begin_close();Box::new(WaveRetirement(self))}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<WaveRetirement>())}fn controlled_retirement_supported()->bool{true}}
